      "Tarangire åbner turen med sin egen rigtige halve dag, plus et stop i Mto wa Mbu og et besøg hos et masai-samfund, der er indbygget i ruten frem for tilbudt som en ekstra tilføjelse — hjemsted for en af de største elefantbestande i Østafrika, koncentreret langs floden i tørtiden. Ngorongoro-krateret får en hel dag i stedet for et forhastet formiddagsstop: en kollapset vulkansk kaldera på omkring 260 km², med sider så stejle, at det meste af det, der lever indeni, aldrig forlader det, og en af de mest koncentrerede dage med dyreliv på hele ruten. To hele dage følger i Serengetis fastboende rovdyrterritorium, før en udsigtsflyvning — med rute gennem Arusha — bytter køretøjet ud med åbent vand og tre uplanlagte nætter på Nungwis hvide sand.",
