        "I nogle få korte uger huser sletterne omkring Ndutu en af de højeste koncentrationer af sårbart ungt dyreliv nogen steder på Jorden — og hvert eneste rovdyr i miles omkreds ved præcis, hvor det skal være. Den spænding former alt ved den måde, disse dage fotograferes på. Køretøjer holder position i stedet for hurtigt at køre videre, fordi historien her ofte tager tid at udfolde sig: en gnu-hunmor der cirkler om en nyfødt, der endnu ikke har fundet sine ben, en gepard der aflæser flokken fra et termitbo, en sjakal der venter i udkanten på sit øjeblik. Jeres guide finder ikke bare dyreliv — de aflæser spændingen, der bygger sig op over sletterne, og hjælper jer med at være i position, før den udløses.",
